custom_css:
/* =====  春日情书-法式磨砂玫瑰  =====
   作者：Rinna@-手机端首发时间@2026-04-11@免费发布于个人群+DC社区欧皇锦鲤食堂&WBZ
   =================== */

/* ===== 说明书 =====
聊天底部边距可自改以安放插件，正文字号大小跟着整体走的，自改部分有注释，请下拉查找
   =================== */

/* 全局字体 */
@import url('https://fonts.googleapis.com/css2?family=Pinyon+Script&family=Playfair+Display:ital,wght@0,500;0,700;1,500&family=Montserrat:wght@400;500;600&family=Cinzel:wght@400;700&family=Cormorant+Garamond:ital,wght@1,500&family=Noto+Serif+SC:wght@500;700;900&display=swap');

:root {
    --font-deco: 'Pinyon Script', cursive;     
    --font-body:  'Playfair Display', 'Noto Serif SC', sans-serif; 
    --font-ui: 'Montserrat', 'Noto Serif SC', 'Huiwen Fangsong', sans-serif;
}

/* 底栏控制台 */
:root {
    --send-bottom-margin: 15px; 
    --send-icon-size: 26px;    
    --send-icon-gap: 10px;     
}

body, .mes_text, textarea, input, select {
    font-family: var(--font-body) !important;
}

#left-nav-panel,
#right-nav-panel {
    height: 100dvh;
    max-height: 100dvh;
}

/* --- 去掉底部消息发送框和上方消息的迷之距离 --- */
#form_sheld {   
    margin: 0 !important;   
}

/* 磨砂玫瑰 (User & AI 共用基础 + 差异镜像) */

/* 共用父容器 */
.mes[is_user="true"],
.mes[is_user="false"] {
    position: relative !important;
    width: 96% !important;
    max-width: 780px !important;
    margin: 10px auto 40px auto !important;
    padding: 260px 0px 60px 0px !important;   
    box-sizing: border-box !important;
    background: rgba(255, 255, 255, 0.55) !important;   
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.7) !important;
    overflow: visible !important;
}

.mes[is_user="true"] .mes_block,
.mes[is_user="false"] .mes_block {
    overflow: visible !important;
    position: relative !important;
    z-index: 2 !important;
}

/* 背景横幅 & 胶带 */
.mes::before {
    content: "" !important;
    position: absolute !important;
    top: 55px !important;
    left: 5% !important;
    width: 90% !important;
    height: 150px !important;
    background: linear-gradient(rgba(200, 135, 142, 0.65), rgba(200, 135, 142, 0.65)), url('https://i.ibb.co/LdFXxMKt/IMG-9066.jpg') !important;
    background-size: cover !important;      
    background-position: center !important;
    background-repeat: no-repeat !important;
    border-radius: 2px !important;
    box-shadow: 2px 4px 10px rgba(0, 0, 0, 0.05) !important;
    z-index: 1 !important;
    pointer-events: none !important;
    border: none !important;
    filter: none !important;
}

.mes[is_user="true"]::after {
    content: "" !important;
    position: absolute !important;
    top: 50px !important;
    left: 2% !important;
    width: 80px !important;
    height: 24px !important;
    background: repeating-linear-gradient(
        -45deg,
        rgba(255, 255, 255, 0.6),
        rgba(255, 255, 255, 0.6) 4px,
        rgba(244, 182, 194, 0.9) 4px,
        rgba(244, 182, 194, 0.9) 8px
    ) !important;
    transform: rotate(-10deg) !important;
    box-shadow: 1px 2px 4px rgba(0, 0, 0, 0.1) !important;
    z-index: 10 !important;
    pointer-events: none !important;
    padding: 0 !important;
    color: transparent !important;
}

.mes[is_user="false"]::after {
    content: "" !important;
    position: absolute !important;
    top: 50px !important;
    right: 2% !important;
    left: auto !important;
    width: 80px !important;
    height: 24px !important;
    background: repeating-linear-gradient(
        -45deg,
        rgba(255, 255, 255, 0.6),
        rgba(255, 255, 255, 0.6) 4px,
        rgba(244, 182, 194, 0.9) 4px,
        rgba(244, 182, 194, 0.9) 8px
    ) !important;
    transform: rotate(10deg) !important;
    box-shadow: 1px 2px 4px rgba(0, 0, 0, 0.1) !important;
    z-index: 10 !important;
    pointer-events: none !important;
    padding: 0 !important;
    color: transparent !important;
}

/* 拍立得头像 */
.mes[is_user="true"] .avatar {
    position: absolute !important;
    top: 25px !important;
    right: 8% !important;
    left: auto !important;
    width: 160px !important;
    height: 200px !important;
    background: #ffffff !important;
    padding: 8px 8px 25px 8px !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: 3px 5px 15px rgba(0, 0, 0, 0.15) !important;
    z-index: 20 !important;
    transform: rotate(15deg) !important;
    margin: 0 !important;
    pointer-events: none !important;
}

.mes[is_user="false"] .avatar {
    position: absolute !important;
    top: 25px !important;
    left: 8% !important;
    right: auto !important;
    width: 160px !important;
    height: 200px !important;
    background: #ffffff !important;
    padding: 8px 8px 25px 8px !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: 3px 5px 15px rgba(0, 0, 0, 0.15) !important;
    z-index: 20 !important;
    transform: rotate(-15deg) !important;
    margin: 0 !important;
    pointer-events: none !important;
}

.mes[is_user="true"] .avatar img,
.mes[is_user="false"] .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 0 !important;
    filter: none !important;
}

/* ch_name 容器 */
.mes[is_user="true"] .ch_name,
.mes[is_user="false"] .ch_name {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 50px !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: visible !important;
    z-index: 15 !important;
    pointer-events: none !important;
}

/* 顶部标语 (差异) */
.mes[is_user="true"] .ch_name::before {
    content: "A hidden Rose without end.@" !important;
    position: absolute !important;
    top: -240px !important;
    left: 13% !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important; 
    color: rgba(0, 0, 0, 0.4) !important; 
    z-index: 20 !important;
}

.mes[is_user="false"] .ch_name::before {
    content: "@ My love for you is silent and long." !important;
    position: absolute !important;
    top: -240px !important;
    right: 5% !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important; 
    color: rgba(0, 0, 0, 0.4) !important; 
    z-index: 20 !important;
    white-space: nowrap !important;
}

/* 名字 (差异)  */
.mes[is_user="true"] .name_text {
    position: absolute !important;
    top: -170px !important;
    left: 10% !important;
    font-family: var(--font-body) !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    color: #ffffff !important;
    letter-spacing: 2px !important;
    text-shadow: 1px 1px 3px rgba(0,0,0,0.1) !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    line-height: 1 !important;
    white-space: nowrap !important;
    pointer-events: none !important;
}

.mes[is_user="false"] .name_text {
    position: absolute !important;
    top: -170px !important;
    right: 30px !important;
    left: auto !important;
    font-family: var(--font-body) !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    color: #ffffff !important;
    letter-spacing: 2px !important;
    text-shadow: 1px 1px 3px rgba(0,0,0,0.1) !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    width: 180px !important;
    white-space: normal !important;
    word-break: break-word !important;
    line-height: 1.3 !important;
    pointer-events: none !important;
    text-align: right !important;
}

/* mesIDDisplay */
.mes[is_user="true"] .mesIDDisplay {
    position: absolute !important;
    top: 175px !important;
    left: 10% !important;
    right: auto !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important;
    color: #ffffff !important;
    background: transparent !important;
    border: none !important;
    text-align: left !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes[is_user="true"] .mesIDDisplay::before { content: "Secrètes " !important; color: #ffffff !important; }
.mes[is_user="true"] .mesIDDisplay::after { content: " roses" !important; color: #ffffff !important; }

.mes[is_user="false"] .mesIDDisplay {
    position: absolute !important;
    top: 175px !important;
    right: 10% !important;
    left: auto !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important;
    color: #ffffff !important;
    background: transparent !important;
    border: none !important;
    text-align: right !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes[is_user="false"] .mesIDDisplay::before { content: "Secrètes " !important; color: #ffffff !important; }
.mes[is_user="false"] .mesIDDisplay::after { content: " roses" !important; color: #ffffff !important; }

/* tokenCounterDisplay (差异) */
.mes[is_user="true"] .tokenCounterDisplay {
    position: absolute !important;
    top: 150px !important;
    left: 10% !important;
    right: auto !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important;
    color: #ffffff !important;
    background: transparent !important;
    border: none !important;
    text-align: left !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes[is_user="true"] .tokenCounterDisplay::before { content: "Mes " !important; }
.mes[is_user="true"] .tokenCounterDisplay::after { content: " rêves" !important; }

.mes[is_user="false"] .tokenCounterDisplay {
    position: absolute !important;
    top: 150px !important;
    right: 10% !important;
    left: auto !important;
    font-family: var(--font-deco) !important;
    font-size: 14px !important;
    color: #ffffff !important;
    background: transparent !important;
    border: none !important;
    text-align: right !important;
    z-index: 20 !important;
    pointer-events: none !important;
}
.mes[is_user="false"] .tokenCounterDisplay::before { content: "Mes " !important; }
.mes[is_user="false"] .tokenCounterDisplay::after { content: " rêves" !important; }

/* 时间戳 */
.mes[is_user="true"] .timestamp,
.mes[is_user="true"] .mes_time {
    position: absolute !important;
    top: -50px !important;
    left: 8% !important;
    font-family: var(--font-body) !important;
    font-size: 13px !important;
    font-weight: 400 !important;
    color: #5a3c42 !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    pointer-events: none !important;
}
.mes[is_user="true"] .timestamp::before,
.mes[is_user="true"] .mes_time::before { content: "" !important; }

.mes[is_user="false"] .timestamp,
.mes[is_user="false"] .mes_time {
    position: absolute !important;
    top: -50px !important;
    right: 8% !important;
    left: auto !important;
    font-family: var(--font-body) !important;
    font-size: 13px !important;
    font-weight: 400 !important;
    color: #5a3c42 !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    pointer-events: none !important;
    text-align: right !important;
}
.mes[is_user="false"] .timestamp::before,
.mes[is_user="false"] .mes_time::before { content: "" !important; }

/* 公共样式（除了位置以外的所有属性） */
.mes[is_user="true"] .mes_buttons,
.mes[is_user="false"] .mes_buttons {
    z-index: 200 !important;
    box-shadow: none !important;
    text-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
    background: none !important;
    display: flex !important;
    gap: 8px !important;
    opacity: 0 !important;
    transition: opacity 0.3s !important;
    pointer-events: auto !important;
    color: #c8878e !important;
}

/* user 专属位置 */
.mes[is_user="true"] .mes_buttons {
    position: absolute !important;
    top: -15px !important;
    right: 15px !important;
}

/* AI 专属位置 */
.mes[is_user="false"] .mes_buttons {
    position: absolute !important;
    top: -22px !important;
    right: 15px !important;
}

/* 去除效果 */
.mes_buttons .mes_button {
  opacity: 1 !important; 
  box-shadow: none !important; 
  text-shadow: none !important;
  transition: none !important; 
  filter: none !important;
  backdrop-filter: none !important;
  border-radius: 0 !important; 
  overflow: visible !important; 
}

.mes[is_user="true"]:hover .mes_buttons,
.mes[is_user="false"]:hover .mes_buttons {
    opacity: 1 !important;
}

.mes .menu_button {
    background-color: #ffffff !important;
    color: #c8878e !important;
    font-size: 0.7rem !important;     
    padding: 2px 6px !important;       
    min-width: unset !important;       
    height: auto !important;           
    line-height: 1.2 !important;       
}

/* 编辑菜单 */
.mes[is_user="true"] .mes_edit_buttons {
    z-index: 200 !important;
    position: absolute !important;   
    right: 90px !important;          
    top: -20px !important;            
    margin-top: 4px !important;      
    pointer-events: auto !important;
}

/* 编辑菜单AI */
.mes[is_user="false"] .mes_edit_buttons {
    z-index: 200 !important;
    position: absolute !important;   
    right: 70px !important;          
    top: -35px !important;            
    margin-top: 4px !important;      
    pointer-events: auto !important;
}

/* 确保内部按钮样式不变 */
.mes[is_user="true"] .mes_edit_buttons button,
.mes[is_user="true"] .mes_edit_buttons .mes_button,
.mes[is_user="false"] .mes_edit_buttons button,
.mes[is_user="false"] .mes_edit_buttons .mes_button {
    pointer-events: auto !important;
    position: relative !important;
    z-index: 200 !important;
}

/* 正文 */
.mes .mes_text {
    margin-top: 0px !important; 
    margin-right: 0 !important;
    margin-left: 0 !important;
    padding-left: 10px !important;
    padding-right: 18px !important;
    font-size: 1.0em !important;
    font-weight: 500 !important;  
    text-shadow: 0 1px 1px rgba(0,0,0,0.1) !important; 
    letter-spacing: 0.5px !important;
    line-height: 1.8 !important;
    text-align: justify !important;    
    color: #4a4545 !important; 
}

/* 增加 AI 正文框的底部内边距 */
.mes[is_user="false"] .mes_text {
    padding-bottom: 60px !important;   /* 有插件要增加改这里 */
}

/* Text Formatting */
/* AI 部分 */
.mes[is_user="false"] .mes_text b, 
.mes[is_user="false"] .mes_text strong { 
    color: #7a5a62 !important; /* 深玫瑰棕 */
    font-weight: 600 !important; 
    background: rgba(216, 155, 166, 0.25) !important; /* 粉色底 */
    padding: 0 4px !important; 
    border-radius: 4px !important; 
    text-shadow: none !important; 
}
.mes[is_user="false"] .mes_text em, 
.mes[is_user="false"] .mes_text i { 
    color: #c87c8c !important; /* 亮粉色 */
    font-weight: 500 !important; 
    font-style: italic !important; 
    background: rgba(255, 235, 240, 0.6) !important; 
    padding: 0 6px !important; 
    border-radius: 6px !important; 
    margin: 0 2px !important; 
    text-shadow: none !important; 
}

/* User 部分 */
.mes[is_user="true"] .mes_text b, 
.mes[is_user="true"] .mes_text strong { 
    color: #8a5a66 !important; 
    font-weight: 600 !important; 
    background: rgba(224, 200, 206, 0.3) !important; 
    padding: 0 4px !important; 
    border-radius: 4px !important; 
    text-shadow: none !important; 
}
.mes[is_user="true"] .mes_text em, 
.mes[is_user="true"] .mes_text i { 
    color: #d89ba6 !important; 
    font-weight: 500 !important; 
    font-style: italic !important; 
    background: rgba(255, 255, 255, 0.5) !important; 
    padding: 0 6px !important; 
    border-radius: 6px !important; 
    margin: 0 2px !important; 
    text-shadow: none !important; 
}

/* 顶部导航横条 */
body.no-blur #top-bar, 
#top-bar {
    background-color: rgba(255, 255, 255, 0.55) !important;   
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border-radius: 16px !important;                                                  
    z-index: 1000 !important;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.7) !important;
}

#top-settings-holder {
    background-color: transparent !important;
    border-radius: 0 !important;
    border-bottom: none !important; 
}

body.waifuMode #top-bar { 
    border-bottom: none !important; 
}

#top-bar {
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.7) !important;
}

/* 顶部栏（磨砂玫瑰） */
/* 隐藏原始字体图标 */
#top-settings-holder .drawer-icon::before {
    opacity: 0 !important;
    visibility: hidden !important;
}

/* 统一图标样式 */
#top-settings-holder .drawer-toggle {
    width: 32px !important;          
    height: 32px !important;         
    background-size: 24px auto !important;  
    margin-top: 10px !important;   
    margin-bottom: 10px !important; 
    background-repeat: no-repeat !important;
    background-position: center !important;
    transition: all 0.2s ease !important;

    /* 正常状态 */
    background-image: url("https://i.ibb.co/0RxnJbTh/D179953-FFDF6-EFAED8-EF8-C49-FB03-D70-B.png") !important;
}

/* 悬停/选中状态 */
#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer-toggle.active,
#top-settings-holder .drawer-toggle:focus {
    background-image: url("https://i.ibb.co/jPLdKKXz/6-DB20384507031-CCB5-ABB3-F5610-E0-BBA.png") !important;
}

/* 法式磨砂玫瑰侧边栏 */

/* 弹出的下拉菜单 (法式磨砂玻璃效果) */
.drawer-content:not(#left-nav-panel):not(#right-nav-panel) {
    background-color: rgba(255, 248, 250, 0.65) !important; 
    backdrop-filter: blur(15px) !important;
    -webkit-backdrop-filter: blur(15px) !important;
    border: 1px solid rgba(255, 255, 255, 0.7) !important; 
    border-radius: 16px !important; 
    padding: 12px 10px !important;
    box-shadow: 0 10px 30px rgba(220, 170, 180, 0.3) !important; 
}

/* 左右两侧的大侧边栏 */
#left-nav-panel, #right-nav-panel {
    background-color: rgba(255, 248, 250, 0.65) !important;
    backdrop-filter: blur(15px) !important;
    -webkit-backdrop-filter: blur(15px) !important;
    background-image: none !important; 
    border: 1px solid rgba(255, 255, 255, 0.7) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.05), inset 0 0 0 1px rgba(255, 255, 255, 0.7) !important;
}

/* 侧边栏与菜单里的大标题 (H2, H3 等) */
.standoutHeader strong, #right-nav-panel h2,
.drawer-content > h3,
.drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter),
.drawer-content .flex-container .flex-container h3:first-of-type,
.popup h3:not(dialog) {
    position: relative !important;
    font-size: calc(var(--mainFontSize) * 1.2) !important; 
    color: #8a5a66 !important; 
    padding-left: calc(var(--mainFontSize) * 1.5) !important; 
    letter-spacing: 1px !important;
    white-space: nowrap !important;
    line-height: 2 !important;
    font-weight: 600 !important;
    text-transform: none !important; 
}

/* 古典花叶符号 ❦ */
.standoutHeader strong::before, #right-nav-panel h2::before,
.drawer-content > h3::before,
.drawer-content .flex-container h3:first-of-type:not(#Backgrounds .textAlignCenter)::before,
.drawer-content .flex-container .flex-container h3:first-of-type::before,
.popup h3:not(dialog *)::before {
    content: "❦" !important; 
    position: absolute !important;
    left: 0 !important;
    color: #d89ba6 !important; 
    font-family: serif !important;
    font-size: calc(var(--mainFontSize) * 1.1) !important;
    line-height: 1 !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    text-shadow: 0 2px 4px rgba(216, 155, 166, 0.4) !important; 
}

/* 分割线 */
.standoutHeader:not(h4), #rm_PinAndTabs,
#top-settings-holder .drawer:not(:first-child):not(:last-child) .drawer-content .alignItemsBaseline.wide100p,
#rm_api_block .flex-container.alignItemsBaseline, #title_api,
#AdvancedFormatting .flex-container.alignItemsBaseline:not(h3),
#WorldInfo .alignitemscenter:not(#world_popup),
#user-settings-block div[name="userSettingsRowOne"],
#rm_extensions_block .alignitemscenter.flex-container.wide100p:not(.justifyCenter) {
    background-image: none !important;
    border-radius: 0 !important;
    border: none !important;
    border-bottom: 2px dashed rgba(216, 155, 166, 0.4) !important; 
    margin-bottom: calc(var(--mainFontSize) * 0.6) !important;
    padding-bottom: calc(var(--mainFontSize) * 0.6) !important;
}
.drawer-content .alignItemsBaseline { align-items: center !important; }

/* 子折叠菜单 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button *):not(#rightNavHolder) {
    border: 1px solid rgba(255, 255, 255, 0.8) !important; 
    border-left: 3px solid rgba(216, 155, 166, 0.8) !important; 
    border-radius: 12px !important; 
    background-color: rgba(255, 255, 255, 0.4) !important; 
    padding: 8px 10px !important;
    margin: 4px 0 !important;
