    padding: 8px 12px !important;
}
#form_sheld { margin: 0 !important; }

/* 左右按钮容器 */
#leftSendForm, #rightSendForm {
    display: flex !important;
    align-items: center !important; 
    gap: var(--send-icon-gap) !important;
}

/* 隐藏原生图标 */
#nonQRFormItems .interactable::before,
#nonQRFormItems .fa-solid::before,
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#stscript_pause::before,
#mes_stop i,
#mes_stop .fa-solid {
    display: none !important;
    content: "" !important;
    width: 0 !important;
    height: 0 !important;
}

/* 准备种花 */
#nonQRFormItems .interactable,
#nonQRFormItems .fa-solid,
#options_button,
#extensionsMenuButton,
#send_but,
#mes_stop,
#quick-reply-rocket-button {
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    width: var(--send-icon-size) !important;
    height: var(--send-icon-size) !important;
    text-shadow: none !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    background-color: transparent !important;
    border: none !important;
    border-radius: 0 !important;
    overflow: visible !important; 
    opacity: 0.8 !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
    color: transparent !important; 
}

/* 种玫瑰 */

/* 粉玫瑰应用给 菜单、扩展、发送按钮 */
#options_button,
#extensionsMenuButton,
#send_but,
#nonQRFormItems .fa-solid {
    background-image: url("https://i.ibb.co/0RxnJbTh/D179953-FFDF6-EFAED8-EF8-C49-FB03-D70-B.png") !important;
}

/* 白玫瑰QR 快捷助手 */
#quick-reply-rocket-button {
    background-image: url('https://i.ibb.co/4gCJ3NTb/6711548093305-DE9-E319-C9-E4-ED0-A2-AC5.png') !important;
    opacity: 0.9 !important;
}

/* 红玫瑰停止生成按钮 */
#mes_stop {
    background-image: url("https://i.ibb.co/jPLdKKXz/6-DB20384507031-CCB5-ABB3-F5610-E0-BBA.png") !important;
    opacity: 0.9 !important;
}

/* 悬停发光 */
#nonQRFormItems .interactable:hover,
#nonQRFormItems .fa-solid:hover,
#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover {
    opacity: 1 !important;
    transform: scale(1.15) rotate(5deg) !important;
    filter: drop-shadow(0 3px 6px rgba(216, 155, 166, 0.7)) !important; 
}
#quick-reply-rocket-button:hover {
    opacity: 1 !important;
    transform: scale(1.15) rotate(5deg) !important;
    filter: drop-shadow(0 3px 6px rgba(255, 255, 255, 0.9)) !important; 
}
#mes_stop:hover {
    opacity: 1 !important;
    transform: scale(1.15) rotate(5deg) !important;
    filter: drop-shadow(0 3px 6px rgba(179, 27, 27, 0.7)) !important; 
}

/* 打字区域 */
#send_form textarea {
    background-color: transparent !important;
    border: none !important;
    color: #8a5a66 !important; 
    font-size: 0.95rem !important;
    font-weight: 400 !important;
    text-shadow: none !important;
    position: relative; 
    z-index: 1;
}

/* 去除原生背景 */
#settings_preset_openai, #openai_inline_image_quality, #openai_reasoning_effort, #openai_logit_bias_preset {
    background-color: transparent !important;
}

/* 父级相对定位 */
#nonQRFormItems { position: relative !important; overflow: visible !important; }


/*  选中头像、欢迎界面 */

/* 欢迎界面留白 */
.welcomePanel {
    background-color: transparent !important;
}

.welcomeRecent,
.welcomeHeaderTitle,
.welcomeHeader {
    background-color: rgba(255, 255, 255, 0.55) !important;
    backdrop-filter: blur(12px) !important;
    border-radius: 16px !important;
    padding: 16px !important;
    border: 1px solid rgba(255, 255, 255, 0.8) !important;
    color: #5a3c42 !important;
    box-shadow: 0 8px 25px rgba(220, 170, 180, 0.15) !important;
    font-family: var(--font-body) !important;
}

/* 头像处理 */
.welcomeRecent .avatar img {
    border-radius: 50% !important;
    border: 2px solid rgba(255, 255, 255, 0.9) !important;
    box-shadow: 0 4px 10px rgba(216, 155, 166, 0.3) !important;
}

.welcomeRecent { padding: 10px 0px !important; }

/* QR Bar */

/* QR 自动收起逻辑 */
#qr--bar {
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    padding-top: 0 !important;
    padding-bottom: 0 !important;
    margin-top: 0 !important;
    margin-bottom: 0 !important;
    pointer-events: none;
    transition: max-height 0.35s ease, opacity 0.25s ease, padding 0.35s ease, margin 0.35s ease;
}
#form_sheld:focus-within #qr--bar {
    max-height: 150px;
    opacity: 1;
    padding-top: 5px !important;
    padding-bottom: 5px !important;
    margin-top: 4px !important;
    margin-bottom: 4px !important;
    pointer-events: auto;
}
#form_sheld:hover #qr--bar {
    max-height: 120px;
    opacity: 1;
    padding-top: 2px !important;
    padding-bottom: 2px !important;
    margin-top: 2px !important;
    margin-bottom: 2px !important;
    pointer-events: auto;
}

/*  QR 按钮本体 */
#qr--bar > .qr--buttons .qr--button,
#qr--popout > .qr--body > .qr--buttons .qr--button {
    background-color: rgba(255, 255, 255, 0.5) !important; 
    backdrop-filter: blur(4px) !important;
    border: 1px solid rgba(255, 255, 255, 0.8) !important; 
    border-radius: 12px !important; 
    font-family: var(--font-ui) !important;
    font-weight: 500 !important;
    font-size: calc(var(--mainFontSize) * 0.85); 
    color: #8F1851 !important; 
    padding: 4px 10px !important;
    box-shadow: 0 2px 6px rgba(220, 170, 180, 0.15) !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
}

/* 标签悬停 */
#qr--bar > .qr--buttons .qr--button:hover,
#qr--popout > .qr--body > .qr--buttons .qr--button:hover {
    background-color: rgba(255, 255, 255, 0.95) !important; 
    border-color: #d89ba6 !important; 
    color: #c87c8c !important; 
    transform: translateY(-2px) !important; 
    box-shadow: 0 4px 10px rgba(220, 170, 180, 0.3) !important; 
}

/* 隐藏自带底色 */
#qr--popoutTrigger { 
    background-color: transparent !important; 
    border: none !important; 
}

/* Avatar Menu */

/* 头像本体 */
.avatar-container .avatar img,
.inline_avatar.avatar img,
.character_select .avatar img,
#avatar_load_preview {
    box-shadow: 0 4px 10px rgba(220, 170, 180, 0.15) !important; 
    border: 2px solid rgba(255, 255, 255, 0.9) !important;
    border-radius: 50% !important;
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
}

/* 鼠标悬停 */
.avatar-container:hover .avatar img,
.character_select:hover .avatar img {
    transform: scale(1.05) !important;
    box-shadow: 0 6px 15px rgba(216, 155, 166, 0.35) !important; 
    border-color: #ffffff !important;
}

/* 隐藏系统默认阴影 */
.character_select.is_fav .avatar, 
.group_select.is_fav .avatar, 
.group_member.is_fav .avatar, 
.avatar.is_fav {
    box-shadow: none !important;
    border: none !important;
}

/* 选中的头像框：粉色磨砂玻璃面纱 */
.avatar-container.selected {
    background-color: rgba(220, 170, 180, 0.5) !important; 
    backdrop-filter: blur(8px) !important; 
    -webkit-backdrop-filter: blur(8px) !important;
    border: 1px solid rgba(255, 255, 255, 0.9) !important; 
    border-radius: 12px !important; 
    box-shadow: 0 4px 10px rgba(220, 170, 180, 0.15) !important; 
    margin-bottom: 10px !important;
    transition: all 0.3s ease !important; 
}

/* 全局隐藏滚动条@感谢导航楼@在到处之间找我老师 */
::-webkit-scrollbar {
  display: none;
}

* { 
    scrollbar-width: none; 
    -ms-overflow-style: none; 
}
